\begin{align*}
\D{}{\sigma}{0}(ff^{r-1})
&= \sum_{\ell(\tau) = \ell(\sigma) - 1}
\D{}{\tau}{0}(f^{r-1})\D{}{\tau,\sigma}{0}(f) \\
&= \sum_{\ell(\tau) = \ell(\sigma) - 1}
\left(\sum_{C(\tau)}\prod_{i=1}^{\ell(\tau)}
\D{}{s_i}{0}(f^{r-1}) \right)
\D{}{\tau,\sigma}{0}(f).
\end{align*}

Now note that $\D{}{\tau,\sigma}{0} = \D{}{s}{0}$ if $\sigma = \tau s$, and otherwise $\D{}{\tau,\sigma}{0} = 0$. This completes the proof.

\begin{Theorem} Let $v \in V$ be standard and let $\gamma \in \Gamma$. Then the Jordan form of the matrix $[\gamma]$ consists of Jordan blocks of size at most $\ell(\omega_0^v)+1$ and eigenvalue $\gamma(v)$. Furthermore, there is at most one block of this maximal size, and for a generic element $\gamma$ of $\Gamma$ there is exactly one such block. \end{Theorem}
